/**
 * 类型面渲染：把收集好的字符串域落成 `Stories.src/gen/stories.gen.d.ts`。
 *
 * 生成物只做一件事——往 `@lingfan/editor` 的注册表接口里塞字面量键。接口声明在词汇层，
 * 经包根再导出后才可被合并；本文件必须带 `export {};`（没有它就是全局脚本，
 * `declare module` 会整体覆盖该模块而不是合并，包出口会被抹掉）。
 *
 * 空集合也照常产出两个空接口：文件在、结构在，但派生类型退化为 `string`——
 * 不拿空注册表把作者的正常写法判红。
 */
import type { TypegenInput } from "./types.ts";

/** 生成物首行：与 gen/fun_register.g.ts 同一惯例，提醒手改会被覆盖 */
const HEADER =
  "/* GENERATED by stories:build (typegen) — 手改会在下次构建被覆盖 */";

/** 渲染时统一走排序去重：语法树里的键序不保证稳定，同输入必须同输出 */
function normalize(values: readonly string[]): string[] {
  return [...new Set(values)].sort();
}

/** 渲染一段接口体；空集产出空接口（保留类型扩充点） */
function renderRegistry(
  lines: string[],
  name: string,
  keys: readonly string[],
  extra: readonly string[] = [],
): void {
  lines.push(`  interface ${name} {`);
  for (const key of normalize(keys)) {
    lines.push(`    ${JSON.stringify(key)}: 1;`);
  }
  for (const line of extra) lines.push(`    ${line}`);
  lines.push("  }");
}

/**
 * 扩展 id → 模式索引签名行。
 *
 * 扩展键由扩展 op 在运行期写入（`extOp("quest", { step })` → `ext.demoquest.step`），
 * 键集静态不可知 ⇒ 只能用模板字面量模式签名表达，枚举字面量键是错形态。
 * 这一行是模板语法而非键名，因此**不能走 `JSON.stringify`**（那会渲染成带引号的普通键，
 * 模式语义全丢）。id 已排序去重，行序稳定。
 */
function extensionSignatures(ids: readonly string[]): string[] {
  return normalize(ids).map((id) => `[k: \`ext.${id}.\${string}\`]: 1;`);
}

/** 渲染类型面全文；末尾带换行，与 renderFunRegister 的收尾一致 */
export function renderTypegen(input: TypegenInput): string {
  const lines: string[] = [];
  lines.push(HEADER);
  lines.push("export {};");
  lines.push("");
  lines.push('declare module "@lingfan/editor" {');
  renderRegistry(lines, "ColumnNameRegistry", input.columns);

  // 插值键域 = state 键、config.vars 键、产物声明名、扩展 id 模式四源并集（合并去重后再排序；
  // defineKeys 现取自 config.ts 的 vars 导出——config 化换道后图谱层不再扫 defineVars）
  renderRegistry(
    lines,
    "InterpolationKeyRegistry",
    [...input.schemaKeys, ...input.defineKeys, ...input.declaredNames],
    extensionSignatures(input.extensionPrefixes),
  );
  lines.push("}");
  return `${lines.join("\n")}\n`;
}
